#include "ui/DeviceCenterComponent.h"
namespace jeff::daw {DeviceCenterComponent::DeviceCenterComponent(){title.setText("Device Center",juce::dontSendNotification);title.setFont(juce::FontOptions(18,juce::Font::bold));devices.setReadOnly(true);devices.setMultiLine(true);for(auto*c:{(juce::Component*)&title,(juce::Component*)&audio,(juce::Component*)&diagnostics,(juce::Component*)&devices})addAndMakeVisible(*c);}void DeviceCenterComponent::setModel(const DeviceCenterModel&m){audio.setText(m.audioMessage(),juce::dontSendNotification);diagnostics.setText(m.diagnostics(),juce::dontSendNotification);juce::String s;for(auto&r:m.rows())s<<r.label<<" — "<<r.status<<juce::newLine;devices.setText(s,false);}void DeviceCenterComponent::resized(){auto r=getLocalBounds().reduced(8);title.setBounds(r.removeFromTop(28));audio.setBounds(r.removeFromTop(26));diagnostics.setBounds(r.removeFromBottom(26));devices.setBounds(r);}}
